1	/**
2	 * Router ขนาดเล็กบน node:http — ไม่ใช้ framework ภายนอกเพื่อให้ระบบไม่มี dependency
3	 */
4	
5	import type { IncomingMessage, ServerResponse } from 'node:http';
6	
7	export interface Ctx {
8	  method: string;
9	  pathname: string;
10	  params: Record<string, string>;
11	  query: URLSearchParams;
12	  body: any;
13	  userId: string;
14	  userRole: string;
15	}
16	
17	type Handler = (ctx: Ctx) => Promise<unknown> | unknown;
18	
19	interface Route {
20	  method: string;
21	  pattern: string;
22	  segments: string[];
23	  handler: Handler;
24	}
25	
26	export class Router {
27	  private routes: Route[] = [];
28	
29	  add(method: string, pattern: string, handler: Handler): void {
30	    this.routes.push({ method, pattern, segments: pattern.split('/').filter(Boolean), handler });
31	  }
32	
33	  private match(method: string, pathname: string): { route: Route; params: Record<string, string> } | null {
34	    const parts = pathname.split('/').filter(Boolean);
35	    for (const route of this.routes) {
36	      if (route.method !== method || route.segments.length !== parts.length) continue;
37	      const params: Record<string, string> = {};
38	      let ok = true;
39	      for (let i = 0; i < parts.length; i++) {
40	        const seg = route.segments[i];
41	        if (seg.startsWith(':')) params[seg.slice(1)] = decodeURIComponent(parts[i]);
42	        else if (seg !== parts[i]) { ok = false; break; }
43	      }
44	      if (ok) return { route, params };
45	    }
46	    return null;
47	  }
48	
49	  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
50	    const url = new URL(req.url ?? '/', 'http://localhost');
51	    const found = this.match(req.method ?? 'GET', url.pathname);
52	
53	    if (!found) {
54	      res.writeHead(404, { 'content-type': 'application/json' });
55	      res.end(JSON.stringify({ error: { code: 'NOT_FOUND', message: 'ไม่พบเส้นทางที่เรียก' } }));
56	      return;
57	    }
58	
59	    let body: any = undefined;
60	    if (req.method === 'POST' || req.method === 'PUT') {
61	      const chunks: Buffer[] = [];
62	      for await (const c of req) chunks.push(c as Buffer);
63	      const raw = Buffer.concat(chunks).toString('utf8');
64	      if (raw) { try { body = JSON.parse(raw); } catch { body = undefined; } }
65	    }
66	
67	    const ctx: Ctx = {
68	      method: req.method ?? 'GET',
69	      pathname: url.pathname,
70	      params: found.params,
71	      query: url.searchParams,
72	      body,
73	      userId: String(req.headers['x-user-id'] ?? ''),
74	      userRole: String(req.headers['x-user-role'] ?? ''),
75	    };
76	
77	    const { status, payload } = await runHandler(found.route.handler, ctx);
78	    res.writeHead(status, { 'content-type': 'application/json' });
79	    res.end(JSON.stringify(payload));
80	  }
81	}
82	
83	/** แยกออกมาเพื่อให้เทสเรียกได้โดยไม่ต้องเปิด server จริง */
84	export async function runHandler(handler: Handler, ctx: Ctx): Promise<{ status: number; payload: unknown }> {
85	  try {
86	    const result = await handler(ctx);
87	    if (result && typeof result === 'object' && 'status' in (result as any) && 'payload' in (result as any)) {
