    throw new DomainError('INVALID_STATE', `ยกเลิกไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  const cutoff = new Date(new Date(state.startAt).getTime() - CANCELLATION_CUTOFF_HOURS * 3600000);
  if (new Date(nowIso()) > cutoff) {
    throw new DomainError(
      'CANCELLATION_TOO_LATE',
      `ยกเลิกไม่ได้ภายใน ${CANCELLATION_CUTOFF_HOURS} ชั่วโมงก่อนเวลาเริ่มใช้งาน`,
      409,
    );
  }
  return [{ type: 'BookingCancelled', bookingId: state.id, occurredAt: nowIso(), actorId, cancelledBy: actorId }];
}

/** เริ่มใช้งานจริง — REQ-23, REQ-29 (การจองเกินเกณฑ์ต้องผ่านการอนุมัติก่อน ตาม REQ-17) */

